<script setup lang="ts">import {computed,ref,watch} from 'vue';import {useRouter} from 'vue-router';import {ArrowRight} from 'lucide-vue-next';import {useResearchData} from '../hooks/useResearch';import {useAuth} from '../stores/auth';import {useAction} from '../hooks/useAction';import {createRun} from '../api/runs';import LibrarySelector from '../components/LibrarySelector.vue';import DataTable from '../components/common/DataTable.vue';import Notice from '../components/common/Notice.vue';const s=useResearchData(),auth=useAuth(),a=useAction(),router=useRouter(),selected=ref(0),chosen=ref<number[]>([]),name=ref(''),sigma=ref(.005),repeats=ref(80),seed=ref(2026);const library=computed(()=>s.libraries.find(l=>l.id===selected.value)||s.libraries[0]);watch(()=>library.value?.id,async id=>{if(id){await s.loadLibrary(id);chosen.value=s.samples.slice(0,3).map(x=>x.id)}},{immediate:true});function submit(){a.execute(async()=>{const run=await createRun({name:name.value,library_id:library.value.id,sample_ids:chosen.value,noise_sigma:sigma.value,repeats:repeats.value,seed:seed.value});router.push('/results?run='+run.id)})}</script><template><div class="page"><div class="page-title"><div><p class="eyebrow">UNMIXING PROTOCOL / 03</p><h1>解混配置<span>非负、和为一，与固定端元假设一起生效。</span></h1></div></div><Notice :message="s.error||a.error.value" @retry="s.refresh"/><div class="editor-grid"><form @submit.prevent="submit"><label>研究名称<input aria-label="研究名称" v-model="name" minlength="2" maxlength="120" required placeholder="例如：首批矿物三样本复配研究" :disabled="auth.user?.role==='viewer'"/></label><LibrarySelector :libraries="s.libraries" :model-value="library?.id||0" @update:model-value="selected=$event"/><div v-if="library&&!library.supported" class="notice">{{library.reason}}</div><div class="form-heading"><span>01</span><h2>选择混合样本</h2></div><div class="sample-selector"><label v-for="sample in s.samples" :key="sample.id"><input type="checkbox" :value="sample.id" v-model="chosen"/><span>{{sample.code}}<small>{{sample.name}}</small></span></label></div><p class="caption">已选{{chosen.length}}个；允许1–6个，样本数×重复数≤480。</p><div class="form-heading"><span>02</span><h2>条件测量噪声</h2></div><div class="form-row"><label>已知测量sigma<input aria-label="测量sigma" type="number" min="0" max=".2" step=".001" v-model.number="sigma"/></label><label>条件重拟合次数<input aria-label="重拟合次数" type="number" min="20" max="120" v-model.number="repeats"/></label></div><label>根随机种子<input aria-label="随机种子" type="number" min="0" max="2147483647" v-model.number="seed"/></label><p class="caption">以观测谱加独立Gaussian噪声，固定端元重拟合。范围不包括端元误差，也不保证真实配比覆盖；sigma=0时扰动退化。</p><button v-if="auth.user?.role!=='viewer'" class="primary" :disabled="a.busy.value||!library?.supported||chosen.length<1||chosen.length>6||chosen.length*repeats>480">提交解混研究 <ArrowRight :size="16"/></button><p v-else class="role-note">阅读者可查看配置，提交研究需要研究员权限。</p></form><aside class="method-note"><span class="eyebrow">METHOD NOTE / 01</span><h2>先检查，<br/>再枚举支持集。</h2><ol><li><b>增广满列秩</b><p>[A;1]需满列秩，条件数≤1e6。秩亏或病态不输出貌似唯一的配比。</p></li><li><b>约束全局最小RSS</b><p>枚举非空支持集，解等式KKT并筛非负；结果再检查完整KKT。</p></li><li><b>条件范围有限</b><p>Gaussian扰动分位不是成分真值置信保证，高残差还可能来自模型失配。</p></li></ol></aside></div></div></template>
